      a: "जी हाँ — यह मार्ग आमतौर पर जुलाई/अगस्त और दिसंबर की स्कूल छुट्टियों के आसपास बुक किया जाता है, और अधिक लचीलेपन वाले परिवारों के लिए इन अवधियों के बाहर भी उतना ही अच्छा काम करता है, जब राष्ट्रीय उद्यान अधिक शांत होते हैं।"
