      "शुरुआत भी महत्वपूर्ण है। यह तारांगिरे के हाथी झुंडों और एक दुर्लभ गाइडेड वॉकिंग सफारी, बिग फाइव के लिए न्गोरोन्गोरो क्रेटर में एक पूर्ण दिन के अवतरण, और ओल्दुवाई गॉर्ज पर एक पड़ाव के साथ शुरू होती है, जो अब तक खोजे गए सबसे महत्वपूर्ण प्रारंभिक मानव जीवाश्मों में से कुछ का स्थल है। वहाँ से यह उत्तर की ओर सेरेनगेटी के मारा नदी क्षेत्र में जाती है, जहाँ महान पलायन की क्रॉसिंग को पकड़ने के लिए तीन लगातार दिन तैनात किए जाते हैं, बजाय अधिकांश छोटे यात्रा कार्यक्रमों द्वारा दिए जाने वाले पासे के एक ही दांव के। दो आवास श्रेणियाँ, Wilderness Trail और Wilderness Sovereign, दोनों एक ही लक्ष्य के इर्द-गिर्द बनाई गई हैं: उस संभावना को अधिकतम करना कि जब झुंड आख़िरकार नदी पार करने का निर्णय लें, तो आप सही जगह पर हों।"
